import { isExpired } from './expiry.mjs';

export function createCache({ capacity = 3, ttl = 1000, now = Date.now } = {}) {
  if (!Number.isInteger(capacity) || capacity <= 0) {
    throw new RangeError('capacity must be a positive integer');
  }
  if (!Number.isFinite(ttl) || ttl < 0) {
    throw new RangeError('ttl must be finite and nonnegative');
  }

  const entries = new Map();

  const prune = () => {
    for (const [key, entry] of entries) {
      if (isExpired(entry, now())) entries.delete(key);
    }
  };

  const touch = (key, entry) => {
    entries.delete(key);
    entries.set(key, entry);
  };

  return {
    set(key, value) {
      prune();
      const existing = entries.get(key);
      if (existing !== undefined) {
        touch(key, { value, deadline: now() + ttl });
        return;
      }
      if (entries.size >= capacity) {
        const lruKey = entries.keys().next().value;
        entries.delete(lruKey);
      }
      entries.set(key, { value, deadline: now() + ttl });
    },
    get(key) {
      prune();
      const entry = entries.get(key);
      if (entry === undefined) return undefined;
      touch(key, entry);
      return entry.value;
    },
    has(key) {
      prune();
      return entries.has(key);
    },
    size() {
      prune();
      return entries.size;
    },
  };
}

