import test from 'node:test';
import assert from 'node:assert/strict';
import { createCache } from '../src/cache.mjs';
test('stores values and evicts oldest inserted key', () => {
  const c = createCache({capacity: 2, ttl: 50, now: () => 0});
  c.set('a', 1); c.set('b', 2); c.set('c', 3);
  assert.equal(c.get('a'), undefined); assert.equal(c.get('b'), 2);
});
test('deadline itself is expired', () => {
  let time = 0; const c = createCache({capacity: 2, ttl: 5, now: () => time});
  c.set('a', 1); time = 5; assert.equal(c.has('a'), false);
});
